FUNCTION_BLOCK FB_Valvula
VAR_INPUT
    nivelAlto : BOOL; // Sensor de nivel alto
END_VAR

VAR_OUTPUT
    valvula : BOOL; // Salida para controlar la válvula
END_VAR

VAR
    timer : TON; // Timer de retardo
    estado : BOOL; // Estado de la válvula
END_VAR

// Inicialización del timer
IF timer.Q = FALSE THEN
    timer(IN := nivelAlto, PT := T#5S);
END_IF;

// Control de la válvula
IF nivelAlto THEN
    // Si el nivel está alto y el timer ha terminado, abrir la válvula
    IF timer.Q THEN
        estado := TRUE;
    END_IF;
ELSE
    // Si el nivel no está alto, cerrar la válvula inmediatamente
    estado := FALSE;
    timer(IN := FALSE); // Reiniciar el timer
END_IF;

// Asignar el estado de la válvula a la salida
valvula := estado;

FUNCTION_BLOCK FB_Valvula
VAR_INPUT
    nivelAlto : BOOL; // Sensor de nivel alto
END_VAR

VAR_OUTPUT
    valvula : BOOL; // Salida para controlar la válvula
END_VAR

VAR
    timer : TON; // Timer de conteo ascendente
    estado : BOOL; // Estado de la válvula
END_VAR

// Inicialización del timer
IF NOT nivelAlto THEN
    timer(IN := FALSE);
    estado := FALSE;
END_IF;

// Control de la válvula
IF nivelAlto THEN
    timer(IN := TRUE, PT := T#5S);
    IF timer.Q THEN
        estado := TRUE;
    END_IF;
ELSE
    estado := FALSE;
    timer(IN := FALSE);
END_IF;

// Asignación de la salida
valvula := estado;

FUNCTION_BLOCK FB_Valvula
VAR_INPUT
    nivelAlto : BOOL; // Indica si el sensor de nivel alto está activo
END_VAR

VAR_OUTPUT
    valvula : BOOL; // Comando para abrir (TRUE) o cerrar (FALSE) la válvula de drenaje
END_VAR

VAR
    temporizador : TON; // Temporizador con retardo a la conexión (On-Delay)
END_VAR

// El temporizador evalúa si el nivel alto se mantiene activo por 5 segundos continuos.
// Si nivelAlto pasa a FALSE, el temporizador se reinicia y su salida Q pasa a FALSE de inmediato.
temporizador(IN := nivelAlto, PT := T#5S);

// La válvula se abre solo cuando el temporizador ha cumplido el tiempo establecido.
valvula := temporizador.Q;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Valvula
VAR_INPUT
    nivelAlto : BOOL; // Sensor de nivel alto del tanque
END_VAR
VAR_OUTPUT
    valvula : BOOL; // Comando para abrir (TRUE) o cerrar (FALSE) la válvula
END_VAR
VAR
    temporizador : TON; // Temporizador de retardo a la conexión (Timer On Delay)
END_VAR

// El temporizador se activa con el sensor de nivel alto.
// Si nivelAlto es TRUE por 5 segundos continuos, la salida Q del temporizador será TRUE.
// Si nivelAlto pasa a FALSE, el temporizador se reinicia y Q pasa a FALSE inmediatamente.
temporizador(IN := nivelAlto, PT := T#5S);

// La válvula se abre solo cuando el temporizador ha cumplido el tiempo establecido.
valvula := temporizador.Q;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Valvula
VAR_INPUT
    nivelAlto : BOOL; // Señal del sensor de nivel alto
END_VAR

VAR_OUTPUT
    valvula : BOOL;   // Comando para abrir (TRUE) o cerrar (FALSE) la válvula
END_VAR

VAR
    tonRetardo : TON; // Temporizador de retardo a la conexión (Timer On Delay)
END_VAR

// Configuración y ejecución del temporizador
// IN: Inicia el conteo si nivelAlto es TRUE. Se resetea inmediatamente si es FALSE.
// PT: Tiempo de retardo establecido en 5 segundos.
tonRetardo(IN := nivelAlto, PT := T#5S);

// La salida del temporizador (Q) se activa tras 5 segundos continuos de nivel alto.
// Si nivelAlto pasa a FALSE, Q se desactiva de inmediato, cerrando la válvula.
valvula := tonRetardo.Q;

END_FUNCTION_BLOCK

